import sys

def solve_n_queens(n, fixed):
    # fixed: dict row->col
    # rows 0..n-1, cols 0..n-1
    board = [-1] * n
    for r, c in fixed.items():
        board[r] = c

    def is_safe(row, col):
        for r in range(n):
            if board[r] == -1:
                continue
            c = board[r]
            if c == col:
                return False
            if abs(r - row) == abs(c - col):
                return False
        return True

    def backtrack(row):
        if row == n:
            return True
        if board[row] != -1:
            return backtrack(row + 1)
        for col in range(n):
            if is_safe(row, col):
                board[row] = col
                if backtrack(row + 1):
                    return True
                board[row] = -1
        return False

    if backtrack(0):
        return board
    return None

