def verify(board):
    n = len(board)
    # Check rows (implicitly unique)
    # Check columns
    cols = set()
    for c in board:
        if c in cols:
            return False
        cols.add(c)
    # Check diagonals
    for i in range(n):
        for j in range(i+1, n):
            if abs(i-j) == abs(board[i]-board[j]):
                return False
    return True

